def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    our_def = 0
    opp_def = 0
    for h in history:
        if h[0] == 'D':
            our_def += 1
        if h[1] == 'D':
            opp_def += 1
    opp_last = history[-1][1]
    my_last = history[-1][0]

    if opp_def == 0:
        if our_def >= 3:
            return 'D'
        if n in (1, 3, 5):
            return 'D'
        return 'C'

    if n >= 99:
        return 'D'
    if n >= 90 and opp_last == 'D':
        return 'D'
    opp_def5 = 0
    start = n - 5
    if start < 0:
        start = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            opp_def5 += 1
    if opp_def5 >= 4:
        return 'D'
    if n >= 2 and opp_def * 2 > n:
        return 'D'
    my_def_last2 = False
    if my_last == 'D':
        my_def_last2 = True
    elif n >= 2 and history[-2][0] == 'D':
        my_def_last2 = True
    if my_def_last2:
        return 'C'
    if opp_last == 'D':
        return 'D'
    return 'C'
